import React, { useState, useEffect } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import { useCart } from "./CartContext";

const navLinks = [
  { to: "/home", label: "HOME", adminOnly: true },
  { to: "/products", label: "PRODUCTS" },
  { to: "/category", label: "CATEGORIES" },
  { to: "/brand", label: "BRANDS" },
  { to: "/aboutus", label: "ABOUT US" },
  {}
];

const Header = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [showDropdown, setShowDropdown] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const email = localStorage.getItem("email") || "Unknown";
  const role = localStorage.getItem("role");
  const { cartItems } = useCart();
  const cartCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
    } else {
      document.body.classList.remove("dark-mode");
    }
  }, [darkMode]);

  return (
    <header className="modern-header" style={{boxShadow: '0 4px 18px rgba(26,35,126,0.10)', minHeight: 72}}>
      <div className="header-bar" />
      <div className="header-container" style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 32, minHeight: 72}}>
        {/* Logo */}
        <div className="logo" onClick={() => navigate('/home')} style={{fontSize: 32, fontWeight: 900, color: 'var(--color-accent)', letterSpacing: 2, display: 'flex', alignItems: 'center', gap: 10, textShadow: '0 2px 8px rgba(0,0,0,0.08)'}}>
          <span style={{ fontSize: 34, verticalAlign: 'middle' }}>🛒</span>
          <span>INVENTORY</span>
        </div>
        {/* Navigation */}
        <nav className={`nav-links${mobileNav ? ' nav-mobile-open' : ''}`} style={{display: 'flex', gap: 36, alignItems: 'center'}}>
          {navLinks.map(link => (
            (!link.adminOnly || role === "admin") && (
              <Link
                key={link.to}
                to={link.to}
                className={location.pathname === link.to ? 'active' : ''}
                style={{
                  fontWeight: 700,
                  fontSize: 18,
                  padding: '8px 22px',
                  borderRadius: 24,
                  background: location.pathname === link.to ? 'rgba(255,152,0,0.13)' : 'none',
                  color: location.pathname === link.to ? 'var(--color-accent)' : '#fff',
                  transition: 'background 0.2s, color 0.2s',
                  position: 'relative',
                  boxShadow: location.pathname === link.to ? '0 2px 8px rgba(255,152,0,0.08)' : 'none',
                  textDecoration: 'none',
                }}
              >
                {link.label}
                {location.pathname === link.to && (
                  <span style={{position: 'absolute', left: 18, bottom: 2, width: 'calc(100% - 36px)', height: 3, background: 'var(--color-accent)', borderRadius: 2}} />
                )}
              </Link>
            )
          ))}
        </nav>
        {/* Actions: dark mode, cart, profile, logout */}
        <div style={{display: 'flex', alignItems: 'center', gap: 18}}>
          <div style={{display: 'flex', alignItems: 'center', gap: 10, background: 'rgba(255,255,255,0.10)', borderRadius: 32, padding: '6px 16px', boxShadow: '0 2px 8px rgba(26,35,126,0.06)'}}>
            {/* Dark Mode Toggle Button */}
            <button
              className="darkmode-toggle"
              aria-label="Toggle dark mode"
              onClick={() => setDarkMode((v) => !v)}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                fontSize: 22,
                color: darkMode ? '#ffb300' : '#fff',
                transition: 'color 0.2s',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: '50%',
                padding: 6,
              }}
            >
              {darkMode ? (
                // Sun icon
                <svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>
              ) : (
                // Moon icon
                <svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M21 12.79A9 9 0 1111.21 3a7 7 0 109.79 9.79z"/></svg>
              )}
            </button>
            {/* Cart Icon with Badge */}
            <div className="cart-icon-container" onClick={() => navigate('/cart')} style={{position: 'relative', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '50%', padding: 6, background: 'rgba(255,255,255,0.08)'}}>
              <svg width="28" height="28" fill="none" viewBox="0 0 24 24" stroke="#fff" strokeWidth="2"><circle cx="9" cy="21" r="1.5"/><circle cx="19" cy="21" r="1.5"/><path d="M2.5 3h2l2.5 13h11l2.5-8H6.5"/></svg>
              <span style={{position: 'absolute', top: 2, right: 2, background: 'var(--color-accent)', color: '#fff', borderRadius: '50%', fontSize: 13, minWidth: 20, height: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, boxShadow: '0 2px 6px rgba(0,0,0,0.12)'}}>{cartCount}</span>
            </div>
            {/* Profile Icon */}
            <div className="profile-container" onClick={() => setShowDropdown(!showDropdown)} style={{marginLeft: 0}}>
              <span className="profile-icon" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, background: 'var(--color-surface)', color: 'var(--color-primary)', width: 36, height: 36, borderRadius: '50%', border: '2px solid var(--color-primary)', boxShadow: '0 2px 8px rgba(26,35,126,0.08)' }}>
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="12" cy="8.5" r="4.5" stroke="currentColor" strokeWidth="2"/>
                  <path d="M4 20c0-2.761 3.582-5 8-5s8 2.239 8 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                </svg>
              </span>
              {showDropdown && (
                <div className="profile-dropdown">
                  <p style={{ margin: 0, fontSize: 13 }}>Logged in as:</p>
                  <strong style={{ fontSize: 14 }}>{email}</strong>
                </div>
              )}
            </div>
          </div>
          {/* Logout Button */}
          <button
            className="logout-btn desktop-only"
            onClick={() => {
              localStorage.removeItem("token");
              localStorage.removeItem("role");
              localStorage.removeItem("name");
              localStorage.removeItem("email");
              navigate("/login");
            }}
            style={{marginLeft: 18, fontWeight: 700, fontSize: 16, borderRadius: 18, padding: '10px 28px', boxShadow: '0 2px 8px rgba(255,152,0,0.08)'}}
          >
            Logout
          </button>
          {/* Hamburger for mobile */}
          <button
            className="hamburger"
            aria-label="Open navigation"
            onClick={() => setMobileNav((v) => !v)}
          >
            <span className="hamburger-bar" />
            <span className="hamburger-bar" />
            <span className="hamburger-bar" />
          </button>
        </div>
      </div>
    </header>
  );
};

export default Header;
